const icons={overview:'▦',website:'▤',crm:'♧',campaigns:'⚑',agent:'✧',workflows:'⌘',analytics:'▥',webinars:'▷',billing:'▣',settings:'⚙'};
const names={overview:'Overview',website:'Websites',crm:'CRM',campaigns:'Campaigns',agent:'AI Agent',workflows:'Workflows',analytics:'Analytics',webinars:'Webinars',billing:'Billing',settings:'Settings'};
let page=location.hash.slice(1)||'home',tab='',hero='Big ideas. Better business.';
const people=[['OL','Olivia Lee','olivia@acme.co','Acme Studio','Qualified','Webinar'],['JW','James Wilson','james@layers.io','Layers','New lead','Website'],['SC','Sophia Chen','sophia@orbit.so','Orbit','Customer','Campaign'],['MR','Michael Reed','michael@pulse.co','Pulse','Qualified','Website'],['AK','Amelia Kim','amelia@mono.io','Mono','Customer','Webinar'],['DB','Daniel Brooks','daniel@forma.co','Forma','New lead','Campaign']];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const badge=(s,c='')=>`<span class="pill ${c}">${s}</span>`;
const btn=(s,a,primary=false)=>`<button class="btn ${primary?'primary':''}" data-action="${a}">${s}</button>`;
function head(t,s,a='',e=''){return `<div class="pagehead"><div>${e?`<div class="eyebrow">${e}</div>`:''}<h1>${t}</h1><p>${s}</p></div><div class="buttons">${a}</div></div>`}
function tabs(a){return `<div class="tabs">${a.map((n,i)=>`<button class="tab ${(tab||a[0])===n?'selected':''}" data-tab="${n}">${n}</button>`).join('')}</div>`}
function metrics(a){return `<div class="metrics">${a.map(([n,v,c,i])=>`<div class="card metric"><div class="metric-top"><span>${n}</span><span class="metric-icon">${icons[i]||'↗'}</span></div><div class="metric-value">${v}</div><div class="metric-foot"><span class="up">↗ ${c}</span><span>vs. previous month</span></div></div>`).join('')}</div>`}
function revenue(){return `<div class="card"><div class="card-head"><div><h2>Revenue overview</h2><p>A clear picture of your business growth</p></div><div class="legend"><span><i class="dot"></i>This month</span><span><i class="dot" style="background:#d5d2e6"></i>Last month</span></div></div><div class="chart-wrap"><svg class="chart" viewBox="0 0 600 205" preserveAspectRatio="none" role="img" aria-label="Illustrative revenue growth over October"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#8d7be2" stop-opacity=".16"/><stop offset="100%" stop-color="#8d7be2" stop-opacity="0"/></linearGradient></defs>${[25,65,105,145].map((y,i)=>`<path d="M42 ${y}H593" stroke="#f0f0f5"/><text x="0" y="${y+4}">$${30-i*10}k</text>`).join('')}<path d="M42 137C62 137 72 115 98 120S134 143 165 112S195 135 225 106S260 111 295 93S326 107 357 82S382 96 409 67S433 64 458 73S485 58 508 60S544 33 571 32S585 31 593 22V167H42Z" fill="url(#area)"/><path class="chartprev" d="M42 144C74 134 83 144 111 134S155 146 185 122S209 137 245 119S270 130 307 111S342 128 372 101S403 118 434 99S466 117 500 89S550 112 593 79"/><path class="chartline" d="M42 137C62 137 72 115 98 120S134 143 165 112S195 135 225 106S260 111 295 93S326 107 357 82S382 96 409 67S433 64 458 73S485 58 508 60S544 33 571 32S585 31 593 22"/>${['Oct 1','Oct 5','Oct 10','Oct 15','Oct 20','Oct 25','Oct 31'].map((d,i)=>`<text x="${42+i*86}" y="190">${d}</text>`).join('')}</svg><div class="chart-footer"><span>Revenue from all connected channels</span><button class="link" data-page="analytics">View report →</button></div></div></div>`}
function journey(){return `<div class="card journey"><div class="card-head"><div><h2>Your customer journey</h2><p>From first visit to lasting customer. All in one place.</p></div><button class="link" data-page="analytics">Explore funnel →</button></div><div class="journey-body">${[['Visitors','24,892','100% of visitors',100,'website'],['Leads','1,284','5.2% conversion',76,'crm'],['Engaged','846','65.9% of leads',59,'campaigns'],['Registered','328','38.8% of engaged',43,'webinars'],['Attended','246','75.0% attendance',31,'webinars'],['Subscribed','89','36.2% conversion',20,'billing']].map(([n,v,s,w,p])=>`<button class="stage" data-page="${p}" style="text-align:left"><div class="stage-top">${icons[p]} ${n}</div><strong>${v}</strong><small>${s}</small><div class="stagebar"><i style="width:${w}%"></i></div></button>`).join('')}</div></div>`}
function contacts(limit=6){return `<div class="table-wrap"><table class="table"><thead><tr><th>CONTACT</th><th>COMPANY</th><th>STATUS</th><th>SOURCE</th><th></th></tr></thead><tbody>${people.slice(0,limit).map((p,i)=>`<tr data-person="${i}" style="cursor:pointer"><td><div class="person"><span class="avatar" style="background:${['#f0e6dc','#e4eaf4','#eee6f5','#e5efeb'][i%4]}">${p[0]}</span><div>${p[1]}<small>${p[2]}</small></div></div></td><td>${p[3]}</td><td>${badge(p[4],p[4]==='Customer'?'green':p[4]==='Qualified'?'purple':'')}</td><td>${p[5]}</td><td>→</td></tr>`).join('')}</tbody></table></div>`}
function activities(){return `<div class="card"><div class="card-head"><h2>Across your business</h2><button class="subtle" data-action="notifications">•••</button></div><div class="timeline">${[['billing','New subscription','Sophia Chen subscribed to the Pro plan.','Billing','2 min ago'],['crm','Lead captured','James Wilson joined from your website.','Website → CRM','18 min ago'],['agent','Campaign ready for review','Nexus AI prepared your webinar follow-up.','AI Agent → Campaigns','42 min ago'],['webinars','Webinar milestone','Growth Masterclass reached 300 registrations.','Webinars','1 hour ago']].map(([i,t,d,m,time])=>`<div class="activity"><span class="activity-icon">${icons[i]}</span><div><p><strong>${t}</strong></p><p>${d}</p><small>${m} · ${time}</small></div></div>`).join('')}</div></div>`}
function overview(){return head('Your business at a glance','Everything is connected. Here’s how your business is doing.',btn('▦ &nbsp; Oct 1 – Oct 31, 2026','date')+btn('✧ &nbsp; Ask Nexus AI','go-agent',true),'Saturday, October 10')+metrics([['Monthly recurring revenue','$24,680','12.8%','billing'],['Total leads','1,284','18.6%','crm'],['Active customers','892','8.2%','crm'],['Website visitors','24,892','24.5%','website']])+`<div class="grid-main">${revenue()}<div class="card agent-card"><div class="card-head"><h2 class="agent-icon"><span class="spark">✧</span>Nexus AI</h2>${badge('● Active','green')}</div><div class="agent-body"><p class="agent-summary">Your business is moving. Here’s what’s next.</p><div class="recommendation"><div style="display:flex;justify-content:space-between;gap:8px"><h3>Turn attendees into customers</h3>${badge('Approval needed','amber')}</div><p>246 people attended your last webinar. A personalized follow-up could bring them closer to a subscription.</p><div class="mini-steps"><span>Webinar</span>→<span>Campaign</span>→<span>Billing</span></div></div><div class="agent-bottom"><span>3 recommendations for you</span>${btn('Review actions →','review')}</div></div></div></div>`+journey()+`<div class="grid-bottom"><div class="card"><div class="card-head"><div><h2>Recent leads & customers</h2><p>The people behind your growth</p></div><button class="link" data-page="crm">View all →</button></div>${contacts(4)}</div>${activities()}</div><div class="bottomnote"><span class="statusline"><i class="dot"></i>All modules connected</span><span>Sample workspace · All data shown is illustrative</span></div>`}
function websites(){const templ=tab==='Templates';return head(templ?'Start with a strong foundation':'Your websites','Your digital storefront, connected to the rest of your business.',btn('+ Create website','new-site',true))+tabs(['Websites','Templates'])+`<div class="sites-grid">${(templ?[['SaaS Modern','SaaS & startups'],['Studio','Agencies & services'],['Gather','Webinars & events'],['Local','Local businesses'],['Mentor','Coaching'],['Product','Product landing page']]:[['Acme main website','acme.nexus.site'],['Growth Masterclass','acme.nexus.site/masterclass'],['Product launch','Draft · Not published']]).map(([n,d],i)=>`<div class="card"><div class="site-cover ${i%3===1?'alt':i%3===2?'orange':''}"><div class="mini-site"><div class="mini-nav"><strong>acme.</strong><span>Product &nbsp; About &nbsp; Contact</span></div><h3>${i%3===0?'Big ideas.<br>Better business.':i%3===1?'Make your next<br>move matter.':'Meet your next<br>big thing.'}</h3><p>Everything you need to grow, in one place.</p><button data-page="builder">Get started →</button></div></div><div class="site-info"><div><h3>${n}</h3><p>${d}</p></div>${badge(templ?'Template':i===2?'Draft':'Published',i===2?'':'green')}</div><div style="padding:0 17px 17px;display:flex;justify-content:space-between">${btn(templ?'Use template →':'Edit website →','go-builder')}<span class="subtle" style="align-self:center">${templ?'8 sections':'Updated 2 hours ago'}</span></div></div>`).join('')}</div>`}
function crm(){return head('Relationships, in one place','A shared view of every lead, customer, and interaction.',btn('Import contacts','import')+btn('+ Add contact','form-contact',true))+tabs(['All contacts','Leads','Customers','Pipeline'])+(tab==='Pipeline'?`<div class="board">${['New lead','Qualified','Proposal','Customer'].map((s,i)=>`<div class="column"><h3>${s} ${badge(i===2?'1':'2')}</h3>${people.filter((p,j)=>i===2?j===0:p[4]===s).map(p=>`<div class="deal"><h3>${p[3]}</h3><p>${p[1]} · ${p[5]}</p><div class="deal-footer"><span>$${i===3?'149':'2,400'}</span>${badge(s,i===3?'green':'purple')}</div></div>`).join('')}</div>`).join('')}</div>`:`<div class="card"><div class="toolbar"><input id="contact-search" class="input filter" placeholder="Search contacts..." aria-label="Search contacts"><select id="status-filter" class="input" style="width:auto" aria-label="Filter by status"><option>All statuses</option><option>New lead</option><option>Qualified</option><option>Customer</option></select></div>${contacts()}<div style="padding:14px 20px;font-size:10px;color:#aaa">Sample contacts · Shared across all modules</div></div>`)}
function campaigns(){return head('Campaigns that move your business forward','Shared audiences. Connected conversations. Measurable results.',btn('+ Create campaign','form-campaign',true))+metrics([['Campaigns','12','20%','campaigns'],['Total recipients','8,460','14.2%','crm'],['Open rate','42.8%','6.3%','analytics'],['Conversions','89','18.1%','billing']])+`<div class="card"><div class="card-head"><h2>Campaigns</h2>${badge('CRM audiences connected','purple')}</div><div class="table-wrap"><table class="table"><thead><tr><th>CAMPAIGN</th><th>AUDIENCE</th><th>STATUS</th><th>OPEN RATE</th><th>CONVERSIONS</th><th></th></tr></thead><tbody>${[['Webinar follow-up','246 attendees','Needs approval','—','—'],['October product update','892 customers','Sent','46.2%','24'],['Welcome to Acme','New website leads','Active','58.4%','42'],['Growth Masterclass invitation','846 engaged leads','Sent','38.1%','23']].map((r,i)=>`<tr><td><strong>${r[0]}</strong><div style="font-size:9px;color:#aaa;margin-top:5px">Email · ${i===0?'Created by Nexus AI':'Acme workspace'}</div></td><td>${r[1]}</td><td>${badge(r[2],i===0?'amber':i===2?'green':'')}</td><td>${r[3]}</td><td>${r[4]}</td><td><button class="link" data-action="${i===0?'review':'campaign-detail'}">Review →</button></td></tr>`).join('')}</tbody></table></div></div>`}
function agent(){return head('A little direction. A lot of possibility.','Your AI partner across every part of your business.',badge('Preview environment','purple'))+`<div class="agent-page"><div class="agent-hero"><div class="spark" style="font-size:30px">✧</div><h1>What should we work on?</h1><p>Start with a goal. Nexus connects the steps.</p></div><div class="card promptbox"><textarea id="prompt" aria-label="Describe your business goal" placeholder="Create a webinar, build a registration page, and prepare a campaign for interested leads..."></textarea><div class="prompt-footer"><span class="subtle">Website · CRM · Growth · Webinars · Billing</span>${btn('Preview plan →','plan',true)}</div></div><div class="suggestions">${['Plan a webinar launch','Follow up with engaged leads','Review business performance'].map(s=>`<button data-prompt="${s}">${s} ↗</button>`).join('')}</div><div class="card"><div class="card-head"><div><h2>Ready for your review</h2><p>Proposed actions stay here until approved.</p></div>${badge('3 actions','amber')}</div>${[['Prepare attendee follow-up','246 webinar attendees · Campaign draft','review'],['Refresh your homepage message','Acme main website · Suggested content','go-builder'],['Review high-intent leads','18 qualified contacts · CRM audience','lead-review']].map(([n,d,a])=>`<div class="planstep"><span class="spark">✧</span><div style="flex:1"><h3>${n}</h3><p>${d}</p></div>${btn('Review',a)}</div>`).join('')}</div></div>`}
function workflows(){return head('Your operations, on autopilot','Connect the journey with clear triggers, steps, and approval gates.',btn('+ Create workflow','form-workflow',true))+`<div class="workflow-grid">${[['Webinar to customer','Follow up with attendees and help turn interest into recurring revenue.','Webinar attended','Follow-up draft','Subscription','Active'],['Welcome new leads','Give every website lead a consistent first experience.','Lead form','CRM contact','Welcome draft','Active'],['High-intent lead nurture','Bring your most engaged prospects closer to a conversation.','Lead qualified','Audience','Campaign draft','Draft'],['Subscription renewal','Keep customers informed as their renewal date approaches.','Renewal date','CRM context','Reminder draft','Draft']].map(([n,d,a,b,c,s])=>`<div class="card workflow"><div style="display:flex;justify-content:space-between"><span class="spark">⌘</span>${badge(s,s==='Active'?'green':'')}</div><h2 style="margin-top:18px">${n}</h2><p>${d}</p><div class="workflow-flow"><span>${a}</span>→<span>${b}</span>→<span>${c}</span></div><div class="workflow-footer"><span>Approval before external actions</span><button class="link" data-action="workflow-detail">View workflow →</button></div></div>`).join('')}</div>`}
function webinars(){return head('Bring your audience together','Create an event page, manage registrations, record attendance, and prepare follow-ups.')+tabs(['Events','Registrations'])+window.NexoraWebinars.render()}
function billing(){return head('Revenue, without the guesswork','Plans, customers, and revenue in one shared view.',btn('+ Create plan','form-billing',true))+metrics([['Monthly recurring revenue','$24,680','12.8%','billing'],['Active subscriptions','892','8.2%','crm'],['Average revenue / customer','$27.67','4.3%','analytics'],['Net revenue retention','108.4%','3.1%','workflows']])+tabs(['Subscriptions','Plans','Usage'])+(tab==='Plans'?`<div class="sites-grid">${[['Starter','29','For businesses getting started','3 team members','1 website','1,000 contacts'],['Pro','149','For growing teams','10 team members','5 websites','10,000 contacts'],['Business','399','For connected operations','Unlimited team members','Unlimited websites','50,000 contacts']].map(([n,p,d,...f],i)=>`<div class="card plan-card ${i===1?'featured':''}"><div style="display:flex;justify-content:space-between"><h2>${n}</h2>${i===1?badge('Popular','purple'):''}</div><p style="margin-top:10px;font-size:11px">${d}</p><div class="plan-price">$${p}<small> / month</small></div><ul>${f.map(s=>`<li>✓ ${s}</li>`).join('')}</ul>${btn('View plan','plan-detail')}</div>`).join('')}</div>`:tab==='Usage'?`<div class="card settings-card"><h2>Workspace usage</h2><p style="margin-bottom:25px">Illustrative usage for October 2026</p>${[['Contacts','1,284 / 10,000',13],['Email volume','8,460 / 20,000',42],['Websites','2 / 5',40],['AI credits','680 / 2,000',34]].map(([n,v,w])=>`<div style="margin:23px 0"><div style="display:flex;justify-content:space-between;font-size:12px"><strong>${n}</strong><span class="subtle">${v}</span></div><div class="stagebar" style="height:7px"><i style="width:${w}%"></i></div></div>`).join('')}</div>`:`<div class="card"><div class="card-head"><h2>Customer subscriptions</h2>${badge('Sample billing data')}</div><div class="table-wrap"><table class="table"><thead><tr><th>CUSTOMER</th><th>PLAN</th><th>STATUS</th><th>MONTHLY REVENUE</th><th>NEXT INVOICE</th></tr></thead><tbody>${people.map((p,i)=>`<tr data-person="${i}" style="cursor:pointer"><td><div class="person"><span class="avatar">${p[0]}</span><div>${p[1]}<small>${p[3]}</small></div></div></td><td>${i%2?'Starter':'Pro'}</td><td>${badge(i===3?'Trialing':'Active',i===3?'purple':'green')}</td><td>$${i%2?'29':'149'}.00</td><td>Nov ${12+i}, 2026</td></tr>`).join('')}</tbody></table></div></div>`)}
function settings(){return head('Workspace settings','The foundation for your connected business.')+tabs(['General','Team','Integrations'])+(tab==='Integrations'?`<div class="card empty"><span class="spark" style="margin:auto">⌘</span><h2 style="margin-top:20px">Your next connections start here</h2><p>Integration settings will live in this space. This concept uses sample data across Nexus modules.</p>${btn('Explore workflows','go-workflows')}</div>`:tab==='Team'?`<div class="card"><div class="card-head"><h2>Workspace team</h2>${btn('Invite member','form-invite',true)}</div><div class="planstep"><span class="avatar">SM</span><div><h3>Stevon Machado</h3><p>Workspace owner</p></div>${badge('Owner','purple')}</div></div>`:`<div class="settings-grid"><div class="card settings-card"><h2>Workspace details</h2><label class="field">Workspace name<input class="input" value="Acme workspace"></label><label class="field">Business name<input class="input" value="Acme Studio"></label><label class="field">Timezone<select class="input"><option>Asia/Kolkata (IST)</option></select></label>${btn('Preview changes','preview',true)}</div><div class="card settings-card"><h2>Brand identity</h2><label class="field">Primary brand color<input class="input" value="#6255CC"></label><label class="field">Display name<input class="input" value="Acme"></label><p>Brand tokens connect your website, email drafts, and registration pages.</p></div></div>`)}
const schema={template:'saas-modern',theme:{primaryColor:'#6255cc',font:'Manrope'},sections:[{type:'navbar'},{type:'hero',variant:'centered',heading:hero},{type:'features'},{type:'testimonials'},{type:'lead-form',binding:'crm'},{type:'pricing',binding:'billing'},{type:'footer'}]};
let selected='Hero';
function builder(){return head('Acme main website','Template-first design. Business components built in.',btn('← Websites','go-website')+btn('Preview','site-preview')+btn('Publish','publish',true))+`<div class="editor"><aside class="editor-panel"><h3>Page sections</h3>${['Navbar','Hero','Features','Testimonials','Lead form','Pricing','Footer'].map(s=>`<button class="section-item ${selected===s?'selected':''}" data-section="${s}" style="width:100%">⠿ ${s}</button>`).join('')}${btn('+ Add section','add-section')}<p style="font-size:10px;margin-top:20px">Predefined sections. Shared brand tokens.</p></aside><div class="editor-preview"><div class="preview-sheet"><div class="preview-nav"><strong style="font-size:14px">acme.</strong><span>Product &nbsp; About &nbsp; Contact</span></div><span class="pill purple" style="margin-bottom:18px">Built for what's next</span><h2 id="preview-heading">${esc(hero)}</h2><p>Bring your ideas, your people, and your next chapter together. Let's build something that matters.</p><button class="btn primary" id="preview-cta" data-action="form-lead" style="background:${schema.theme.primaryColor}">Let's get started →</button><div class="preview-features"><div class="preview-feature">One shared workspace</div><div class="preview-feature">Meaningful connections</div><div class="preview-feature">Room to grow</div></div><div style="margin-top:38px;font-size:10px;color:#999">Trusted by ambitious teams<br><br><strong style="font-size:16px;color:#8f8e9f;word-spacing:22px">Layers Orbit Pulse</strong></div></div></div><aside class="editor-panel"><h3>${selected} settings</h3><label class="field">Heading preview<textarea id="hero-input" class="input" rows="3">${esc(hero)}</textarea></label><label class="field">Variant<select class="input" id="variant"><option>Centered</option><option>Left aligned</option></select></label><label class="field">Brand color<input type="color" id="brand-color" value="${schema.theme.primaryColor}" style="width:100%;height:35px;border:1px solid #eee;margin-top:6px"></label><label class="field">Font<select class="input" id="font"><option>Manrope</option><option>DM Sans</option><option>Arial</option></select></label><label class="field">Business binding<select class="input"><option>CRM · Lead capture</option><option>Webinars · Registration</option><option>Billing · Pricing plans</option></select></label><p style="font-size:10px">Temporary UI preview · Predefined sections stored as structured data.</p></aside></div>`}
function render(){document.getElementById('app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">N</span>nexus<span style="font-size:10px;letter-spacing:0;color:#b3abc9;align-self:flex-start;margin-top:7px">®</span></div><div class="workspace"><span class="workspace-logo">A</span><div><strong style="font-size:11px">Acme workspace</strong><small>Business plan</small></div><span style="margin-left:auto;color:#aaa">⌄</span></div>${Object.entries(names).map(([id,n],i)=>`${i===1?'<div class="navlabel">Workspace</div>':''}${i===3?'<div class="navlabel">Growth & operations</div>':''}${i===9?'<div style="height:12px"></div>':''}<button class="nav ${page===id||page==='builder'&&id==='website'?'active':''}" data-page="${id}"><span style="width:17px;font-size:18px;text-align:center">${icons[id]}</span>${n}${id==='agent'?'<span class="count">3</span>':''}</button>`).join('')}<div class="sidebar-bottom"><button class="nav" data-action="help">ⓘ &nbsp; Help & resources</button><div class="tip"><strong style="font-size:11px">Your business, connected.</strong><p>One workspace. Every stage of your customer journey.</p><a href="#agent">Explore Nexus AI →</a></div><div class="profile"><span class="avatar">SM</span><div><strong style="font-size:11px">Stevon Machado</strong><small>Workspace owner</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><button class="mobile-menu" data-action="menu" aria-label="Toggle navigation">☰</button><span>Workspace</span><span>/</span><strong>${names[page]||'Website builder'}</strong></div><div class="topactions"><button class="search" data-action="search"><span>⌕ &nbsp; Search anything...</span><kbd>Ctrl K</kbd></button><span class="demo">UI concept</span><span class="divider"></span><button data-action="notifications" aria-label="Notifications">♧</button><span class="avatar" style="width:27px;height:27px">SM</span></div></header><div class="content" id="content"></div></main></div>`;renderContent()}
function renderContent(){const views={overview,website:websites,crm,campaigns,agent,workflows,analytics,webinars,billing,settings,builder};document.getElementById('content').innerHTML=(views[page]||overview)();if(page==='crm'){filter();window.NexoraWebinars.loadContacts()}if(page==='webinars')window.NexoraWebinars.refresh()}
function go(p){page=p;tab='';location.hash=p;render();window.scrollTo(0,0)}
function toast(s){const t=document.getElementById('toast');t.textContent=s;t.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.style.display='none',4000)}
let lastFocus;
function modal(t,b,f=''){lastFocus=document.activeElement;document.getElementById('overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(t)}"><div class="modal-head"><h2>${t}</h2><button data-action="close" aria-label="Close dialog">×</button></div><div class="modal-body">${b}</div><div class="modal-footer">${btn('Close','close')}${f}</div></section></div>`;document.querySelector('.modal button').focus()}
function close(){document.getElementById('overlay').innerHTML='';lastFocus?.focus()}
function detail(i){const p=people[i];modal(p[1],`<div class="person" style="margin-bottom:22px"><span class="avatar">${p[0]}</span><div><h3>${p[3]}</h3><small>${p[2]}</small></div></div>${badge(p[4],'purple')}<h3 style="margin-top:24px">Connected customer activity</h3>${[['Visited Acme website','Website · Oct 2'],['Joined the CRM','CRM · Oct 3'],['Registered for Growth Masterclass','Webinars · Oct 5'],['Attended Growth Masterclass','Webinars · Oct 8'],['Included in follow-up draft','Campaigns · Oct 10']].map(([n,d])=>`<div class="planstep"><span class="stepnum">✓</span><div><h3>${n}</h3><p>${d}</p></div></div>`).join('')}`,btn('View campaigns →','go-campaigns'))}
function review(){modal('Review proposed campaign',`<p>Nexus AI prepared a follow-up for the Growth Masterclass audience. Review the message and connected steps.</p><div class="detail-stat"><div><strong>246</strong><small>Webinar attendees</small></div><div><strong>1</strong><small>Email draft</small></div><div><strong>Pro</strong><small>Linked plan</small></div></div><label class="field">Subject<input class="input" value="Your next step after Growth Masterclass"></label><div class="recommendation"><h3>Thanks for joining us.</h3><p>You took the first step toward a more connected business. Explore how Acme can help you put what you learned into practice.</p>${badge('CTA: Explore the Pro plan','purple')}</div><p style="font-size:10px">UI preview · Approval does not send a campaign.</p>`,btn('Request revision','revision')+btn('Approve preview','approve',true))}
const forms={contact:['Add contact',['Name','Email','Company']],campaign:['Create campaign',['Campaign name','CRM audience','Subject']],webinar:['Create webinar',['Event title','Date & time','Description']],billing:['Create plan',['Plan name','Monthly price','Currency']],workflow:['Create workflow',['Workflow name','Trigger','Next step']],invite:['Invite member',['Name','Email']],lead:['Lead capture',['Name','Email']]};
function action(a){if(a.startsWith('go-')){close();return go(a.slice(3))}if(a==='close')return close();if(a==='menu')return document.querySelector('.sidebar').classList.toggle('open');if(a==='review')return review();if(a.startsWith('form-')){const [t,fields]=forms[a.slice(5)];return modal(t,`<p>Explore this form in the UI concept. No records are saved and no external actions occur.</p>${fields.map(n=>`<label class="field">${n}<input class="input" placeholder="${n}" ${n==='Email'?'type="email"':''}></label>`).join('')}`,btn('Preview','preview',true))}if(['preview','approve','revision'].includes(a)){close();return toast(a==='approve'?'Approval previewed. No campaign was sent.':a==='revision'?'Revision requested in this preview.':'Preview complete. No changes are persisted.')}if(a==='new-site'){go('website');tab='Templates';return renderContent()}if(a==='plan'){const q=document.getElementById('prompt').value.trim();if(!q)return toast('Describe a business goal to preview a plan.');return modal('Proposed execution plan',`<p>${esc(q)}</p>${[['Understand the goal','Review the mock customer and business context.'],['Prepare the assets','Draft event, audience, and template-based page changes.'],['Request approval','Review the audience, messages, and publication changes.'],['Measure the journey','Link suggested analytics to registrations and subscriptions.']].map(([n,d],i)=>`<div class="planstep"><span class="stepnum">${i+1}</span><div><h3>${n}</h3><p>${d}</p></div></div>`).join('')}<p style="font-size:10px;margin-top:20px">Illustrative plan · No AI model or execution service is connected.</p>`,btn('Keep as preview draft','preview',true))}if(a==='date')return modal('Reporting period','<p>This sketch shows an illustrative October reporting period.</p><label class="field">Start date<input class="input" type="date" value="2026-10-01"></label><label class="field">End date<input class="input" type="date" value="2026-10-31"></label>',btn('Preview period','preview',true));if(a==='search')return modal('Search your workspace',`<input id="global-search" class="input" placeholder="Find a module..." aria-label="Search modules"><div style="margin-top:15px">${Object.entries(names).map(([id,n])=>`<button class="nav" data-searchpage="${id}">${icons[id]} ${n}</button>`).join('')}</div>`);if(a==='notifications')return modal('Workspace activity',activities());if(a==='publish')return modal('Review website publication','<p>This concept includes a hero, predefined sections, a CRM lead form, and billing plan bindings.</p><div class="recommendation"><h3>Acme main website</h3><p>acme.nexus.site · Template: SaaS Modern</p><span class="pill purple">Draft preview</span></div><p>No customer website will be published from this sketch.</p>',btn('Approve preview','preview',true));if(a==='site-preview')return modal('Website preview',document.querySelector('.preview-sheet').outerHTML);if(a==='add-section')return modal('Predefined section library',`<p>Choose a section to explore its settings.</p><div class="suggestions">${['Hero','Features','Testimonials','Lead form','Pricing','FAQ','Webinar registration','Footer'].map(s=>`<button data-addsection="${s}">${s} +</button>`).join('')}</div>`);if(a==='lead-review')return modal('High-intent audience preview','<p>Sample contacts qualified by website visits, email engagement, and webinar participation.</p>'+contacts(4));if(a==='workflow-detail')return modal('Workflow preview',`<p>Every step uses shared customer context.</p>${[['Trigger','Webinar attendance recorded'],['Prepare','Match attendees to CRM contacts'],['Draft','Prepare a personalized follow-up campaign'],['Approval','Wait for workspace owner review'],['Measure','Connect engagement to subscriptions']].map(([n,d],i)=>`<div class="planstep"><span class="stepnum">${i+1}</span><div><h3>${n}</h3><p>${d}</p></div></div>`).join('')}`);if(a==='campaign-detail')return modal('Campaign performance','<p>October product update · Sample customer audience</p><div class="detail-stat"><div><strong>892</strong><small>Recipients</small></div><div><strong>46.2%</strong><small>Open rate</small></div><div><strong>24</strong><small>Conversions</small></div></div><p>CRM → Campaigns → Billing → Analytics</p>');if(a==='plan-detail')return modal('Plan configuration','<p>Recurring plan with website pricing bindings. No billing changes occur.</p><label class="field">Billing interval<select class="input"><option>Monthly</option><option>Annual</option></select></label><label class="field">Pricing model<select class="input"><option>Flat recurring</option><option>Usage-based</option></select></label>');if(a==='import')return modal('Import contacts preview','<p>Import fields map to the shared CRM record.</p><div class="empty" style="padding:30px;border:1px dashed #ddd"><h3>Contact import placeholder</h3><p>Name · Email · Company · Lifecycle stage</p></div>');if(a==='report')return modal('October report preview','<p>One shared journey across Website, CRM, Campaigns, Webinars, and Billing.</p><div class="detail-stat"><div><strong>24,892</strong><small>Visitors</small></div><div><strong>1,284</strong><small>Leads</small></div><div><strong>$24,680</strong><small>Monthly revenue</small></div></div><p>Sample data · Export generation is outside this frontend phase.</p>');if(a==='help')return modal('Welcome to your Nexus concept','<p>Explore modules, inspect connected customer activity, edit the website preview, or ask the AI Agent for an illustrative plan.</p><p>All business data is mocked. Forms and approvals are temporary previews.</p>')}
function filter(){const q=document.getElementById('contact-search')?.value.toLowerCase()||'';const s=document.getElementById('status-filter')?.value||'All statuses';document.querySelectorAll('#content [data-person]').forEach(r=>{const p=people[+r.dataset.person];r.hidden=!(p.join(' ').toLowerCase().includes(q)&&(s==='All statuses'||p[4]===s)&&(tab!=='Customers'||p[4]==='Customer')&&(tab!=='Leads'||p[4]!=='Customer'))})}
document.addEventListener('click',e=>{const b=e.target.closest('[data-page],[data-action],[data-tab],[data-person],[data-prompt],[data-section],[data-addsection],[data-searchpage],[data-event]');if(!b){if(e.target.classList.contains('modal-backdrop'))close();return}if(b.dataset.page)go(b.dataset.page);if(b.dataset.action)action(b.dataset.action);if(b.dataset.tab){tab=b.dataset.tab;renderContent()}if(b.dataset.person!==undefined)detail(+b.dataset.person);if(b.dataset.prompt){document.getElementById('prompt').value=b.dataset.prompt;document.getElementById('prompt').focus()}if(b.dataset.section){selected=b.dataset.section;renderContent()}if(b.dataset.addsection){selected=b.dataset.addsection;close();renderContent();toast(`${selected} settings previewed.`)}if(b.dataset.searchpage){close();go(b.dataset.searchpage)}if(b.dataset.event)modal(b.dataset.event,`<p>Connected event information and performance preview.</p><div class="detail-stat"><div><strong>328</strong><small>Registered</small></div><div><strong>246</strong><small>Attended</small></div><div><strong>89</strong><small>Subscribed</small></div></div><p>Registration page → CRM → Webinar → Campaign follow-up</p>`,btn('Review follow-up','review',true))});
document.addEventListener('input',e=>{if(e.target.id==='contact-search')filter();if(e.target.id==='global-search')document.querySelectorAll('[data-searchpage]').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(e.target.value.toLowerCase()));if(e.target.id==='hero-input'){hero=e.target.value;schema.sections[1].heading=hero;document.getElementById('preview-heading').textContent=hero}if(e.target.id==='brand-color'){schema.theme.primaryColor=e.target.value;document.getElementById('preview-cta').style.background=e.target.value}});
document.addEventListener('change',e=>{if(e.target.id==='status-filter')filter();if(e.target.id==='variant'){schema.sections[1].variant=e.target.value;document.querySelector('.preview-sheet').style.textAlign=e.target.value==='Centered'?'center':'left'}if(e.target.id==='font'){schema.theme.font=e.target.value;document.querySelector('.preview-sheet').style.fontFamily=e.target.value;document.getElementById('preview-heading').style.fontFamily=e.target.value}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();action('search');document.getElementById('global-search').focus()}if(e.key==='Tab'&&document.querySelector('.modal')){const a=[...document.querySelectorAll('.modal button,.modal input,.modal select,.modal textarea')].filter(x=>!x.hidden),f=a[0],l=a.at(-1);if(e.shiftKey&&document.activeElement===f){e.preventDefault();l.focus()}else if(!e.shiftKey&&document.activeElement===l){e.preventDefault();f.focus()}}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1)||'home';if(p!==page){page=p;tab='';render()}});render();

